<template><section><div class="mb-6"><h1 class="text-2xl font-black">Mis favoritos</h1><p class="text-sm text-slate-500">Productos guardados desde Flutter o la web.</p></div><p v-if="error" class="alert-error mb-4">{{ error }}</p><div v-if="cargando" class="card p-10 text-center">Cargando...</div><div v-else-if="productos.length" class="grid gap-5 sm:grid-cols-2 xl:grid-cols-4"><ProductCard v-for="p in productos" :key="p.id" :producto="p" /></div><div v-else class="card p-10 text-center text-slate-500">Todavía no tienes favoritos.</div></section></template>
<script setup>import{onMounted,ref}from'vue';import ProductCard from'../components/ProductCard.vue';import authService from'../services/authService.js';import favoritoService from'../services/favoritoService.js';const productos=ref([]),cargando=ref(true),error=ref('');onMounted(async()=>{try{productos.value=await favoritoService.obtener(authService.obtenerUsuario().id);}catch(e){error.value=e.response?.data?.mensaje||'No se pudieron cargar';}finally{cargando.value=false;}});</script>
